import csv, os, re
from collections import Counter
p = os.path.join(os.environ["PANTHEON_PROJECTS"], "survey/cafe.csv")
rows = list(csv.DictReader(open(p, newline="", encoding="utf-8-sig")))
who = {c for c in rows[0] if re.search(r"name|e-?mail|phone|address", c, re.I)}
mask = lambda t: re.sub(r"\+?\d[\d ]{8,}\d", "[phone]", re.sub(r"\S+@\S+", "[email]", t))
for c in [c for c in rows[0] if c not in who]:
    vals = [r[c].strip() for r in rows if r[c].strip()]
    if len(set(vals)) <= 10 or all(v.isdigit() for v in vals):
        print("CLOSED", c, len(vals), "answered", Counter(vals).most_common())
    else:
        print("OPEN", c, len(vals), "answered")
        for i, v in enumerate(vals, 1): print(f"  {i}. {mask(v)[:300]}")

